const input=document.querySelector("#home-search-input");input&&(document.querySelectorAll("[data-search-url]").forEach(e=>{e.addEventListener("click",()=>{const t=input.value.trim();if(!t){input.focus();return}const n=e.dataset.searchUrl.replace("{query}",encodeURIComponent(t));window.open(n,"_blank","noopener,noreferrer")})}),input.addEventListener("keydown",e=>{e.key==="Enter"&&(e.preventDefault(),input.closest(".home-search")?.querySelector("[data-search-url]")?.click())}))